from research_helpers import *
B=ev('https://americanbatterytechnology.com/press-release/american-battery-technology-company-receives-approval-for-sale-of-100-million-of-exported-recycled-black-mass-critical-minerals-with-license-from-u-s-department-of-commerce/','October1 2026 issuer confirms active commercial recycling outputs: copper, aluminum, steel, lithium-rich intermediate and black mass. Export license is permission, not a claim of completed100million sales.')
F=ev('https://investors.americanbatterytechnology.com/faq/','Issuer differentiates first-stage recycling intermediates from second-stage battery-grade refined outputs. No unsupported specific salt or purity grade invented.')
T=ev('https://americanbatterytechnology.com/technologies/','Issuer distinguishes demonstrated claystone lithium hydroxide from future commercial buildout; graphite recovery remains research/development.')
ps=[]
for name,desc in [('recycled black mass','Battery recycling intermediate containing lithium, nickel, cobalt, manganese and graphite.'),('lithium-rich recycling intermediate','First-stage lithium-bearing recycling output for further refining.'),('recycled copper','Copper recovered from end-of-life batteries and manufacturing scrap.'),('recycled aluminum','Aluminum recovered from end-of-life batteries and manufacturing scrap.'),('recycled steel','Steel recovered from end-of-life batteries and manufacturing scrap.')]:ps.append(p('ABTC '+name,desc,B,'commercial',roles=['manufacturer'],typ='product',sector='energy_storage',sub='batteries',attributes={'category':'battery_recycling_material','exact_grade_or_purity':'not disclosed in reviewed evidence'}))
ps.append(p('ABTC battery-grade lithium hydroxide','Battery cathode feedstock demonstrated from Nevada claystone; commercial mine/refinery buildout remains prospective.',T,'development',typ='product',sector='energy_storage',sub='batteries',attributes={'commercial_scale_status':'demonstration batches; commercial buildout prospective'},evidence=[T,F]))
for metal in ['nickel','cobalt','manganese']:ps.append(p('ABTC battery-grade '+metal+' refining programme','Battery-grade '+metal+' output planned through selective hydrometallurgical refining; exact saleable salt/grade and current commercial delivery not established.',F,'development',sector='energy_storage',sub='batteries'))
ps.append(p('ABTC anode-grade graphite recovery programme','Recovery and purification of battery graphite.',T,'research',sector='energy_storage',sub='batteries'))
cs=[company('American Battery Technology Company Common Stock',ps,[B,F,T],'Current October2026 commercial first-stage outputs and disclosed downstream development programmes reviewed. No facility or mining claim treated as battery SKU. Refining programme records do not assert commercial nickel/cobalt/manganese sales. Further product-grade specifications, patent-level process identities and hydrometallurgical deployment status require followup.')]
(out/'batch-0065.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
